<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Accessor\ClientIdentityRolesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ClientIdentityRolesAccessor trait.
 *
 * Covers null default, string/VO assignment via withRoles,
 * getRoles/roles accessors, and isRolesChanged with/without original.
 */
class ClientIdentityRolesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRoles creates a new instance with the Roles set
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromString(): void
    {
        // Arrange
        $holder = new ImplWithClientIdentityRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRoles());
    }
    /**
     * Asserts that withroles has access to the value object
     * from a string value, and getRoles returns the primitive string.
     */
    public function testWithRolesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithClientIdentityRolesAccessorUnitTest();

        // Act
        $result = $holder->withRoles('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->roles()->value());
    }
    public function testChangedRoles(): void
    {
        // Arrange
        $holder = new ImplWithClientIdentityRolesAccessorUnitTest();
        $original = $holder->withRoles('one');
        $same = $holder->withRoles('one');
        $modified = $holder->withRoles('other');

        // Act
        $unchanged = $holder->isRolesChanged();
        $withSame = $original->isRolesChanged($same);
        $withDiferent = $original->isRolesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithClientIdentityRolesAccessorUnitTest
{
    use ClientIdentityRolesAccessor;
}
